// 🏫 UNIVERSIDADE CASTELO BRANCO — ETL CORRIGIDO E BLINDADO

const map = {
  'MATRICULA': 'MATRÍCULA',
  'NOME ALUNO': 'ALUNO',
  'CURSO': 'CURSO',
  'CPF': 'CPF RESPONSÁVEL',
  'DATA DE NASCIMENTO': 'DATA NASCIMENTO',
  'ENDEREÇO': 'ENDEREÇO',
  'BAIRRO': 'BAIRRO',
  'CIDADE': 'CIDADE',
  'CEP': 'CEP',
  'ESTADO': 'ESTADO',
  'TELEFONE 1': 'TELEFONE 1',
  'TELEFONE 2': 'TELEFONE 2',
  'RESPONSÁVEL': 'NOME RESPONSÁVEL',
  'REFERENCIA': 'ID PARCELA',
  'DATA VENCIMENTO': 'VENCIMENTO',
  'VALOR PARCELA': 'LÍQUIDO',
  'EMAIL': 'EMAIL'
};

// 🔤 normalização (remove acento + case insensitive)
const normalize = str =>
  str
    ? str.toString()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .trim()
    : '';

// 🧹 limpeza
const limparAspas = v =>
  v !== null && v !== undefined
    ? v.toString().replace(/""/g,'').replace(/['"]/g,'').trim()
    : '';

const limparEndereco = v =>
  v ? v.toString().replace(/[.,;:]/g,'').trim() : '';

const limparEmail = v =>
  v ? v.toString().replace(/['"]/g,'').trim() : '';

// 🪪 CPF
const formatarCPF = v => {
  if (!v) return '="00000000000"';
  const num = v.toString().replace(/\D/g,'');
  return `="${num.padStart(11,'0').slice(0,11)}"`;
};

// 🔢 REFERENCIA — 11 dígitos com zeros à esquerda e protegido no Excel
const formatarReferencia = v => {
  if (!v) return '="00000000000"';

  const num = v.toString().replace(/\D/g, '');
  const ref = num.padStart(11, '0').slice(-11);

  return `="${ref}"`;
};

// 📅 DATA — AAAAMMDD, incluindo número serial do Excel
const formatarData = v => {
  if (v === null || v === undefined || v === '') return '';

  const s = v.toString().trim();

  // já está no formato AAAAMMDD
  if (/^\d{8}$/.test(s)) return s;

  // formato dd/mm/yyyy
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [d, m, a] = s.split('/');
    return `${a}${m.padStart(2, '0')}${d.padStart(2, '0')}`;
  }

  // formato yyyy-mm-dd
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const [a, m, d] = s.split('-');
    return `${a}${m}${d}`;
  }

  // número serial do Excel
  if (/^\d+$/.test(s)) {
    const serial = parseInt(s, 10);

    // faixa razoável para datas Excel
    if (serial > 20000 && serial < 60000) {
      const base = new Date(Date.UTC(1899, 11, 30));
      base.setUTCDate(base.getUTCDate() + serial);

      const ano = base.getUTCFullYear();
      const mes = String(base.getUTCMonth() + 1).padStart(2, '0');
      const dia = String(base.getUTCDate()).padStart(2, '0');

      return `${ano}${mes}${dia}`;
    }
  }

  // fallback comum
  const d = new Date(s);
  if (!isNaN(d)) {
    return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
  }

  return '';
};

// 💰 VALOR
const formatarValor = v => {
  if (!v) return '="0,00"';

  let limpo = v.toString().replace(/[^\d.,-]/g,'');

  if (limpo.includes(',') && limpo.includes('.')) {
    limpo = limpo.replace(/\./g,'');
  }

  limpo = limpo.replace(',','.');

  let num = parseFloat(limpo);
  if (isNaN(num)) num = 0;

  return `="${num.toFixed(2).replace('.',',')}"`;
};

// 👤 RESPONSÁVEL
const limparResponsavel = v => {
  if (!v) return '';

  return v
    .toString()
    .replace(/["']/g,'')
    .replace(/\d{1,2}\/\d{1,2}\/\d{2,4}/g,'')
    .replace(/;/g,'')
    .replace(/""/g,'')
    .trim();
};

// 📥 leitura
let inputData = $input.all().map(i => i.json);

if (inputData.length === 1 && Array.isArray(inputData[0].data)) {
  inputData = inputData[0].data;
}

// 🧭 headers inteligentes
const headers = {};
if (inputData.length) {
  Object.keys(inputData[0]).forEach(k => {
    headers[normalize(k)] = k;
  });
}

// 🔍 getValue inteligente
const getValue = (row, col) => {
  const variations = [
    col,
    col.replace(/_/g,' '),
    col.replace(/ /g,'_')
  ];

  for (const v of variations) {
    const key = headers[normalize(v)];
    if (key) return row[key];
  }

  return '';
};

// 🧱 processamento
const output = inputData.map(row => {
  const novo = {};

  for (const [saida,entrada] of Object.entries(map)) {
    let valor = limparAspas(getValue(row, entrada));

    switch(saida){
  case 'ENDEREÇO':
    valor = limparEndereco(valor);
    break;

  case 'CPF':
    valor = formatarCPF(valor);
    break;

  case 'DATA DE NASCIMENTO':
  case 'DATA VENCIMENTO':
    valor = formatarData(valor);
    break;

  case 'VALOR PARCELA':
    valor = formatarValor(valor);
    break;

  case 'RESPONSÁVEL':
    valor = limparResponsavel(valor);
    break;

  case 'EMAIL':
    valor = limparEmail(valor);
    break;

  case 'REFERENCIA':
    valor = formatarReferencia(valor);
    break;
}

    novo[saida] = valor;
  }

  return { json: novo };
});

// remove só linhas vazias
return output.filter(item =>
  Object.values(item.json).some(v => v && v.toString().trim() !== '')
);
